CREATE TABLE public.eventos (
    id integer NOT NULL,
    codigo character varying(50) NOT NULL,
    nombre character varying(150) NOT NULL,
    descripcion text,
    anio integer NOT NULL,
    fecha_inicio date NOT NULL,
    fecha_fin date NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    creado_en timestamp with time zone DEFAULT now(),
    cupo_maximo integer DEFAULT 400 NOT NULL,
    lugar_nombre character varying(150),
    direccion character varying(200),
    ciudad character varying(100),
    horario_apertura character varying(10) DEFAULT '08:00'::character varying,
    horario_cierre character varying(10) DEFAULT '18:30'::character varying,
    lema character varying(250),
    estado character varying(30) DEFAULT 'PUBLICADO'::character varying,
    sede_nombre character varying(255) DEFAULT 'Auditorio Polo Saavedra'::character varying,
    sede_direccion character varying(255) DEFAULT 'Crisólogo Larralde 5085, Buenos Aires'::character varying,
    sede_mapa_url text DEFAULT 'https://maps.google.com/maps?q=Cris%C3%B3logo+Larralde+5085,+Buenos+Aires&t=&z=15&ie=UTF8&iwloc=&output=embed'::text
);


